import com.wolinski.shop.money.Money;
import com.wolinski.shop.payments.api.PaymentLookup;
import com.wolinski.shop.payments.api.PaymentsFacade;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class LastPaymentTest {

    @Test
    void lastPaymentIsNotFoundForAnOrderWithoutPayments() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            PaymentsFacade payments = shop.getBean(PaymentsFacade.class);

            PaymentLookup lookup = payments.lastPayment("no-such-order");

            assertFalse(lookup.found());
            assertNull(lookup.payment());
        }
    }

    @Test
    void lastPaymentIsTheMostRecentCharge() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            PaymentsFacade payments = shop.getBean(PaymentsFacade.class);

            payments.charge("o-1", Money.pln(1000));
            payments.charge("o-1", Money.pln(250));

            PaymentLookup lookup = payments.lastPayment("o-1");

            assertTrue(lookup.found());
            assertEquals(Money.pln(250), lookup.payment().amount());
            assertEquals("CAPTURED", lookup.payment().status());
        }
    }
}
}
